"""
State Capture Mechanism
Records exact system state when thresholds are breached for post-mortem analysis.
"""
import os
import sys
import json
import time
import signal
from datetime import datetime
from typing import Optional, Dict, Any
import subprocess
import traceback
import psutil


class StateCapture:
    """
    Captures exact system state when thresholds are breached.

    Captures:
    - Process tree (pstree)
    - Open files (lsof)
    - Memory dump (optional, large)
    - Stack traces
    - Environment variables (configurable)
    """

    def __init__(
        self,
        output_dir: str = "state_snapshots",
        retention_days: int = 7,
        include_stack_traces: bool = True,
        capture_env_vars: bool = False
    ):
        self.output_dir = output_dir
        self.retention_days = retention_days
        self.include_stack_traces = include_stack_traces
        self.capture_env_vars = capture_env_vars

    def ensure_output_dir(self):
        """Create output directory if it doesn't exist."""
        os.makedirs(self.output_dir, exist_ok=True)

    def get_timestamp_filename(self) -> str:
        """Generate timestamped filename for snapshot."""
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        return f"snapshot_{ts}.json"

    def capture_process_tree(self) -> Dict[str, Any]:
        """Capture process tree using pstree command."""
        try:
            result = subprocess.run(
                ['pstree', '-p'],
                capture_output=True,
                text=True,
                timeout=5
            )
            return {
                'command': 'pstree -p',
                'output': result.stdout.strip(),
                'error': result.stderr.strip() if result.returncode != 0 else None
            }
        except subprocess.TimeoutExpired:
            return {'command': 'pstree -p', 'output': '', 'error': 'Timeout'}
        except Exception as e:
            return {'command': 'pstree -p', 'output': '', 'error': str(e)}

    def capture_open_files(self) -> Dict[str, Any]:
        """Capture open files using lsof command."""
        try:
            result = subprocess.run(
                ['lsof'],
                capture_output=True,
                text=True,
                timeout=10
            )
            return {
                'command': 'lsof',
                'output': result.stdout.strip()[:5000],  # Limit size
                'error': result.stderr.strip() if result.returncode != 0 else None
            }
        except subprocess.TimeoutExpired:
            return {'command': 'lsof', 'output': '', 'error': 'Timeout'}
        except Exception as e:
            return {'command': 'lsof', 'output': '', 'error': str(e)}

    def capture_memory_dump(self) -> Optional[Dict[str, Any]]:
        """
        Capture memory dump using psutil.

        Returns None if disabled or fails (memory dumps are large).
        """
        # Memory dumps are typically too large for regular snapshots
        # Only capture if explicitly enabled via config flag
        return None

    def capture_stack_traces(self) -> Dict[str, Any]:
        """Capture stack traces of all processes."""
        if not self.include_stack_traces:
            return {'stack_traces': []}

        traces = {}
        try:
            for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
                try:
                    pid = proc.info['pid']
                    name = proc.info['name'] or str(pid)
                    cmdline = proc.info.get('cmdline')

                    # Get stack trace using pstack
                    result = subprocess.run(
                        ['pstack', str(pid)],
                        capture_output=True,
                        text=True,
                        timeout=2
                    )
                    traces[name] = {
                        'pid': pid,
                        'cmdline': cmdline,
                        'trace': result.stdout.strip() if result.returncode == 0 else None
                    }
                except (subprocess.TimeoutExpired, Exception):
                    pass
        except Exception as e:
            return {'stack_traces': [], 'error': str(e)}

        return {'stack_traces': list(traces.values())}

    def capture_environment(self) -> Dict[str, Any]:
        """Capture environment information."""
        env_info = {
            'timestamp': datetime.now().isoformat(),
            'python_version': sys.version,
            'platform': platform = sys.platform,
            'cwd': os.getcwd()
        }

        if self.capture_env_vars:
            # Capture only relevant environment variables
            env_info['env_vars'] = {
                key: value
                for key, value in os.environ.items()
                if any(keyword in key.lower() for keyword in [
                    'python', 'path', 'home', 'user', 'app'
                ])
            }

        return env_info

    def capture_system_metrics(self) -> Dict[str, Any]:
        """Capture current system metrics."""
        import psutil

        metrics = {
            'timestamp': datetime.now().isoformat(),
            'cpu_percent': psutil.cpu_percent(interval=1),
            'memory_percent': psutil.virtual_memory().percent,
            'disk_percent': psutil.disk_usage('/').percent,
            'load_avg': list(psutil.getloadavg()) if hasattr(psutil, 'getloadavg') else None
        }

        return metrics

    def capture_full_state(self) -> Dict[str, Any]:
        """
        Capture complete system state.

        Returns:
            Dictionary containing all captured state information
        """
        self.ensure_output_dir()
        filename = self.get_timestamp_filename()
        filepath = os.path.join(self.output_dir, filename)

        snapshot = {
            'metadata': {
                'timestamp': datetime.now().isoformat(),
                'retention_days': self.retention_days,
                'include_stack_traces': self.include_stack_traces,
                'capture_env_vars': self.capture_env_vars
            },
            'system_metrics': self.capture_system_metrics(),
            'process_tree': self.capture_process_tree(),
            'open_files': self.capture_open_files(),
            'stack_traces': self.capture_stack_traces(),
            'environment': self.capture_environment()
        }

        # Write snapshot to file
        with open(filepath, 'w') as f:
            json.dump(snapshot, f, indent=2, default=str)

        return {
            'success': True,
            'filepath': filepath,
            'snapshot': snapshot
        }

    def cleanup_old_snapshots(self):
        """Remove snapshots older than retention period."""
        import shutil
        cutoff = datetime.now() - timedelta(days=self.retention_days)

        for filename in os.listdir(self.output_dir):
            if not filename.startswith('snapshot_'):
                continue
            filepath = os.path.join(self.output_dir, filename)
            mtime = datetime.fromtimestamp(os.path.getmtime(filepath))

            if mtime < cutoff:
                try:
                    os.remove(filepath)
                except OSError:
                    pass
